import requests, xml.etree.ElementTree as ET
u='https://eutils.ncbi.nlm.nih.gov/entrez/eutils/efetch.fcgi'
r=requests.get(u,params={'db':'pubmed','id':'10755520','retmode':'xml'},timeout=20); print('status',r.status_code)
root=ET.fromstring(r.text)
for node in root.findall('.//ArticleTitle'): print('TITLE:', ''.join(node.itertext()))
for node in root.findall('.//Abstract/AbstractText'): print('ABSTRACT:', node.attrib.get('Label',''), ''.join(node.itertext()))
for node in root.findall('.//Author'): 
 parts=[node.findtext('LastName'),node.findtext('Initials')]
 if parts[0]: print('AUTHOR:', ' '.join(x for x in parts if x))
for node in root.findall('.//Journal/Title'): print('JOURNAL:',node.text)
for node in root.findall('.//PubDate'): print('DATE:', ' '.join(''.join(x.itertext()) for x in node))
